/* decode as firedancer does: y reduced mod p, x = 0 accepted with either sign; the point as
   (X, Y, 1, T) */
static inline int
fd_adx_point_frombytes( ulong r[16], const uchar b[32] ) {
  int sign = b[31] >> 7;
  ulong y[4], y2[4], u[4], v[4], x[4];
  fd_fe64_frombytes( y, b );
  fd_fe64_sqr( y2, y );
  fd_fe64_sub( u, y2, fd_adx_one );                      /* u = y^2 - 1 */
  fd_fe64_mul( v, y2, fd_adx_d ); fd_fe64_add( v, v, fd_adx_one );  /* v = d y^2 + 1 */
  if( !fd_fe64_sqrt_ratio( x, u, v ) ) return 0;
  if( fd_fe64_sgn( x ) != sign ) { ulong nx[4]; fd_fe64_neg( nx, x ); memcpy( x, nx, 32 ); }
  memcpy( r, x, 32 ); memcpy( r+4, y, 32 ); memcpy( r+8, fd_adx_one, 32 ); fd_fe64_mul( r+12, x, y );
  return 1;
}

/* X = 0, Y = 0, or Y the y of an order-8 point, for a decoded point (Z = 1) */
static inline int
fd_adx_point_is_small_order_affine( const ulong a[16] ) {
  return fd_fe64_is_zero( a ) || fd_fe64_is_zero( a+4 ) || fd_fe64_eq( a+4, fd_adx_order8_y0 ) || fd_fe64_eq( a+4, fd_adx_order8_y1 );
}

/* the canonical affine coordinates of a (1/Z checked) and the RFC 8032 encoding */
static inline void
fd_adx_point_affine_canon( ulong cx[4], ulong cy[4], const ulong a[16] ) {
  ulong zi[4], ax[4], ay[4];
  fd_fe64_inv( zi, a+8 ); fd_fe64_mul( ax, a, zi ); fd_fe64_mul( ay, a+4, zi );
  fd_fe64_canon( cx, ax ); fd_fe64_canon( cy, ay );
}
static inline void
fd_adx_encode_canon( uchar out[32], const ulong cx[4], const ulong cy[4] ) {
  for( int i=0; i<4; i++ ) fd_adx_store8_le( out + 8*i, cy[i] );
  out[31] ^= (uchar)((cx[0] & 1ULL) << 7);
}
static inline int
fd_adx_affine_is_small_order( const ulong cx[4], const ulong cy[4] ) {
  return (cx[0]|cx[1]|cx[2]|cx[3])==0ULL || (cy[0]|cy[1]|cy[2]|cy[3])==0ULL || memcmp( cy, fd_adx_order8_y0, 32 )==0 || memcmp( cy, fd_adx_order8_y1, 32 )==0;
}

/* a == b for b with Z = 1: X_b Z_a == X_a and Y_b Z_a == Y_a */
static inline int
fd_adx_point_eq_z1( const ulong a[16], const ulong b[16] ) {
  ulong mx[4], my[4]; fd_fe64_mul( mx, b, a+8 ); fd_fe64_mul( my, b+4, a+8 );
  return fd_fe64_eq( mx, a ) && fd_fe64_eq( my, a+4 );
}

/* -P: negate X and T */
static inline void fd_adx_point_neg( ulong r[16], const ulong a[16] ) {
  ulong nx[4], nt[4]; fd_fe64_neg( nx, a ); fd_fe64_neg( nt, a+12 );
  memcpy( r, nx, 32 ); memcpy( r+4, a+4, 32 ); memcpy( r+8, a+8, 32 ); memcpy( r+12, nt, 32 );
}
/* -(table entry): swap Y+X and Y-X, negate 2dT */
static inline void fd_adx_table_neg( ulong r[16], const ulong q[16] ) {
  memcpy( r, q+4, 32 ); memcpy( r+4, q, 32 ); memcpy( r+8, q+8, 32 ); fd_fe64_neg( r+12, q+12 );
}

/* tab[j] = [2j+1]A in table form, j < cnt */
static inline void
fd_adx_odd_table( ulong tab[][16], const ulong a[16], int cnt ) {
  ulong p[16], p2[16]; memcpy( p, a, 128 );
  fd_ge_adx_dbl_asm( p2, p );
  fd_ge_adx_to_table_asm( tab[0], p );
  for( int j=1; j<cnt; j++ ) { fd_ge_adx_add_asm( p, p, p2 ); fd_ge_adx_to_table_asm( tab[j], p ); }
}

/* r = [2^n] a */
static inline void fd_adx_point_dbln( ulong r[16], const ulong a[16], int n ) {
  if( r != a ) memcpy( r, a, 128 );
  for( int i=0; i<n; i++ ) fd_ge_adx_dbl_asm( r, r );
}

