/* A from ea and R from er, both always attempted: bit 0 set when A decoded, bit 1 when R did */
static inline int fd_adx_point_decode2( ulong a[16], uchar const ea[32], ulong r[16], uchar const er[32] ) {
  int oa = fd_adx_point_frombytes( a, ea );
  int orr = fd_adx_point_frombytes( r, er );
  return oa | (orr << 1);
}
static inline int fd_adx_point_decode1( ulong p[16], uchar const e[32] ) { return fd_adx_point_frombytes( p, e ); }


