/* The checks of fd_ed25519_verify on one signature, in its order and with its codes: returns the
   first failing check's code, else FD_ED25519_SUCCESS having set *_ok to whether the group equation
   holds when *_ok was nonzero on entry (with *_ok zero the equation is not evaluated). a_tbl, when
   not NULL, is the cached split table of -A: A then is known to decode and not to be of small
   order, and R is checked by re-encoding the computed point (its canonical encoding equal to the
   signature's R means R decodes to that point, encodings of canonical form being unique); the
   lanes where it differs decode R, which also yields their codes. Without a table, A and R are
   decoded (or, in the implementations that re-encode, A alone and R only where the re-encoding
   differs) and neg_a (when not NULL) receives the decoded -A once the equation was evaluated, for
   the cache's admission. */
int
fd_adx_verify_core( uchar const msg[], ulong msg_sz, uchar const sig[ 64 ], uchar const public_key[ 32 ], fd_sha512_t * sha,
                    fd_adx_tbl_t const * a_tbl, int * _ok, ulong * neg_a );

/* the transaction verdict from per-signature codes: the first that is neither SUCCESS nor
   ERR_MSG, else ERR_MSG when any equation failed, else SUCCESS (verify.c) */
int fd_adx_verdict( int const codes[], ulong n );

